    struct PtySession {
        child: Box<dyn portable_pty::Child + Send>,
        master: Arc<Mutex<Box<dyn MasterPty + Send>>>,
        writer: Arc<Mutex<Box<dyn Write + Send>>>,
        parser: vt100::Parser,
        last_size: Option<(u16, u16)>,
        bytes_received: u64,
        output_event_count: u64,
        scroll_offset: usize,
        /// Whether the auto-PS1 command has already been sent for this session.
        ps1_auto_sent: bool,
        /// Accumulates user-typed bytes between Enter presses so we can
        /// detect commands like `sudo su` / `sudo su - <user>` and re-run
        /// the prep-terminal sequence after the new shell prompt appears.
        input_line_buf: String,
        /// Set when the most recently submitted line was a `sudo su` form;
        /// the next prompt detected in output triggers re-prep.
        pending_reprep: bool,
        /// Accounts this tab's shell has switched into via `sudo su`, most
        /// recent last; popped by `exit` / `logout` / Ctrl-D. Empty means
        /// the tab is still on the login the SSM session opened as.
        ///
        /// This is what "the currently logged in user" means for an upload.
        /// It cannot be answered by asking the box: the file browser runs on
        /// its own hidden control channel (`ensure_control_channel`), a
        /// separate SSM session that knows nothing about a `sudo su` typed
        /// in the visible terminal. So it is tracked from what was typed,
        /// which is also why the Upload button names the account it will
        /// hand the file to before you pick a file.
        session_user_stack: Vec<String>,
        /// Trimmed text of the cursor-line prompt the last time PREP was
        /// auto-fired. Used to ensure we only re-prep when a *new*
        /// shell prompt appears (e.g., after `sudo su`), not on every
        /// subsequent output flush.
        last_prepped_prompt: String,
        /// When the most recent paste was written to the PTY, and how many
        /// bytes it contained. Used to log the echo-return latency of large
        /// pastes so we can distinguish remote-buffering stalls from local
        /// parse/render stalls. Cleared once we log the first inbound byte.
        paste_write_at: Option<Instant>,
        paste_write_bytes: usize,
        /// Counter incremented each time the parser observes a fresh shell
        /// prompt at the cursor line. Paired with a Condvar so the paste
        /// worker can wait for the remote shell to be ready between lines
        /// instead of blindly sleeping a fixed delay. Without this, slow
        /// commands (e.g. `sudo systemctl daemon-reload`) consume queued
        /// stdin bytes as their own input, so subsequent pasted lines get
        /// echoed but never executed.
        prompt_ready: Arc<(Mutex<u64>, Condvar)>,
        /// Whether the cursor was at a prompt at the end of the previous
        /// parser frame. Used to bump `prompt_ready` only on a false→true
        /// transition (cursor newly arrived at a prompt). Without this, idle
        /// frames at the prompt keep bumping the counter, which lets the
        /// paste worker's `wait_timeout_while` return prematurely between
        /// snapshot and wait — gluing the next pasted line onto a still-
        /// running command. See `paste_to_connection_tab`.
        at_prompt_last_frame: bool,
        /// Absolute row (scrollback lines + cursor row) where we last bumped
        /// `prompt_ready`. A fresh prompt after a command lands on a *new*
        /// absolute row, so we can bump even when the command's echo and the
        /// redrawn prompt arrive in the same parser frame (no false→true
        /// dip). An idle re-observation stays on the same row, so it still
        /// won't bump (which would glue pasted lines). See the bump site.
        last_prompt_abs_row: Option<usize>,
        /// When this PTY was spawned — used to log how long the SSM
        /// session takes to connect (diagnosing slow connections).
        spawned_at: Instant,
        /// Whether the "SSM session connected" timing has been logged.
        connect_logged: bool,
    }

    /// Absolute terminal position: scroll-invariant coordinate.
    /// `abs_row` 0 = newest line (bottom at scroll_offset 0), increasing into history.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    struct AbsPos {
        abs_row: usize,
        col: u16,
    }

    #[derive(Clone, Debug, Default)]
    struct TerminalSelection {
        anchor: Option<AbsPos>, // where drag started
        end: Option<AbsPos>,    // where drag is now
    }

    impl TerminalSelection {
        /// Returns (start, end) in reading order: start has higher abs_row
        /// (further into history / top of display), end has lower abs_row
        /// (closer to present / bottom of display).
        fn normalized(&self) -> Option<(AbsPos, AbsPos)> {
            let a = self.anchor?;
            let e = self.end?;
            if a.abs_row > e.abs_row || (a.abs_row == e.abs_row && a.col <= e.col) {
                Some((a, e))
            } else {
                Some((e, a))
            }
        }

        #[allow(dead_code)]
        fn is_active(&self) -> bool {
            self.anchor.is_some() && self.end.is_some()
        }

        fn clear(&mut self) {
            self.anchor = None;
            self.end = None;
        }

        /// True when the user has selected something — anchor and end both
        /// set, and covering more than the single cell a bare click leaves
        /// behind. This is the test right-click copy uses to decide
        /// copy-vs-paste.
        fn has_real_span(&self) -> bool {
            self.normalized().is_some_and(|(s, e)| s != e)
        }
    }

    /// What a Copy event means for a terminal tab.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum TerminalCopyAction {
        /// Ctrl+Shift+C — copy the terminal's own drag-selection.
        CopyTerminalSelection,
        /// Plain Ctrl+C with something highlighted outside the terminal.
        LeaveToOutsideHighlight,
        /// Plain Ctrl+C with nothing highlighted — the shell's interrupt.
        Interrupt,
    }

    /// egui emits `Event::Copy` for Ctrl+C with or without shift, so the
    /// modifiers have to be read separately to tell the two apart.
    fn terminal_copy_action(shift: bool, outside_highlight: bool) -> TerminalCopyAction {
        if shift {
            TerminalCopyAction::CopyTerminalSelection
        } else if outside_highlight {
            TerminalCopyAction::LeaveToOutsideHighlight
        } else {
            TerminalCopyAction::Interrupt
        }
    }

    /// True when the user has text highlighted in a widget *outside* the
    /// terminal — the instance-id summary line above it, say. egui owns that
    /// selection (its labels are selectable by default) and copies it itself
    /// on Ctrl+C, so the terminal's only job is to not also send an interrupt.
    fn outside_highlight_active(ctx: &egui::Context) -> bool {
        ctx.with_plugin::<egui::text_selection::LabelSelectionState, _>(|s| s.has_selection())
            .unwrap_or(false)
    }

    fn clear_outside_highlight(ctx: &egui::Context) {
        ctx.with_plugin::<egui::text_selection::LabelSelectionState, _>(|s| s.clear_selection());
    }

    /// Whether this key event drops a highlight made outside the terminal.
    fn key_event_drops_outside_highlight(
        event: &egui::Event,
        has_text: bool,
        has_key_backspace: bool,
    ) -> bool {
        match event {
            // Both halves of one Ctrl+C press: egui emits `Event::Copy` *and*
            // `Event::Key{C, ctrl}` for it. Ctrl+C is the key that reads the
            // highlight, so neither may clear it.
            egui::Event::Copy | egui::Event::Cut => false,
            egui::Event::Key { key: egui::Key::C, modifiers, .. }
                if modifiers.ctrl || modifiers.command =>
            {
                false
            }
            // Anything else the terminal actually receives is typing. A key
            // it ignores (Ctrl+Shift+C, a bare modifier) sends no payload and
            // so leaves the highlight alone.
            _ => terminal_event_payload_for_terminal(event, has_text, has_key_backspace)
                .is_some(),
        }
    }

