        // --- Obfuscated user-management shell templates ------------------
        // These used to be inline `format!` string literals; they now live in
        // obfuscated asset blobs. Each test decrypts the blob, substitutes the
        // username, and checks the reconstructed shell is intact — that the
        // build-time obfuscation round-trips, the placeholder is fully
        // replaced, and the recognizable command signature survived.

        fn deobf_named(blob: &[u8], user: &str) -> String {
            deobf_asset(blob).replace("__USER__", user)
        }

        #[test]
        fn create_diagnostics_template_round_trips() {
            let s = deobf_named(
                include_bytes!(concat!(env!("OUT_DIR"), "/create_diagnostics.sh.obf")),
                "jane.doe",
            );
            assert!(!s.contains("__USER__"), "placeholder not substituted");
            assert!(s.starts_with("U=\"jane.doe\""), "got: {s}");
            assert!(s.contains("authorized_keys") && s.contains("getent passwd"));
        }

        #[test]
        fn delete_preflight_template_round_trips() {
            let s = deobf_named(
                include_bytes!(concat!(env!("OUT_DIR"), "/delete_preflight.sh.obf")),
                "jane.doe",
            );
            assert!(!s.contains("__USER__"));
            // Single line, no trailing newline (fed straight to `base64 -d`).
            assert!(!s.contains('\n'), "preflight must stay one line");
            assert!(s.contains("id jane.doe >/dev/null") && s.contains("CNU_ABSENT"));
        }

        #[test]
        fn delete_diagnostics_template_round_trips() {
            let s = deobf_named(
                include_bytes!(concat!(env!("OUT_DIR"), "/delete_diagnostics.sh.obf")),
                "jane.doe",
            );
            assert!(!s.contains("__USER__"));
            assert!(s.starts_with("U=\"jane.doe\""));
            assert!(s.contains("pgrep -u") && s.contains("/efs/home/"));
        }

        #[test]
        fn secondary_mirror_template_round_trips() {
            let s = deobf_named(
                include_bytes!(concat!(env!("OUT_DIR"), "/secondary_mirror.sh.obf")),
                "jane.doe",
            );
            assert!(!s.contains("__USER__"));
            // One compound command, no trailing newline (one step in a vec).
            assert!(!s.contains('\n'), "secondary must stay one line");
            assert!(s.starts_with("cd ~ && H=/efs/home/jane.doe;"));
            assert!(s.contains("useradd -u") && s.contains("groupadd -g"));
            // A failure has to name itself. Reporting only "FAILED to create"
            // and discarding useradd's own sentence is what made a broken
            // secondary undiagnosable from the screen.
            assert!(s.contains("secondary: FAILED to create jane.doe"));
            assert!(s.contains("|| echo \"secondary: useradd failed: $UERR\""));
            assert!(s.contains("|| echo \"secondary: groupadd failed: $GERR\""));
            assert!(s.contains("held by: $(getent passwd"));
        }

        /// The mirror step retries for ~24s, so it must match the branch that
        /// gives it 40s rather than the 6s `STEP_WAIT`. These two lived in
        /// different files and silently drifted apart once already: the
        /// matcher looked for `stat -c %u /efs/home` after the script had been
        /// refactored to `stat -c %u "$H"`, and nothing failed — the step just
        /// started timing out, letting the next step be sent into a shell that
        /// was still running this one.
        #[test]
        fn secondary_mirror_step_matches_its_wait() {
            let s = deobf_named(
                include_bytes!(concat!(env!("OUT_DIR"), "/secondary_mirror.sh.obf")),
                "jane.doe",
            );
            assert!(
                s.contains(SECONDARY_MIRROR_MARK),
                "the mirror step must contain SECONDARY_MIRROR_MARK ({SECONDARY_MIRROR_MARK:?}) \
                 or it silently falls back to the 6s STEP_WAIT; step was: {s}"
            );
        }

        /// The dump has to name the same three record types `parse_dump`
        /// reads, and must not filter the in-use tables: a uid held by a
        /// *system* account still blocks a useradd, so a conflict report built
        /// from the managed accounts alone would miss it and the apply would
        /// fail against a number it had called free.
        #[test]
        fn user_sync_dump_reports_managed_accounts_and_every_id_in_use() {
            let s = deobf_asset(include_bytes!(concat!(
                env!("OUT_DIR"),
                "/user_sync_dump.sh.obf"
            )));
            assert!(s.contains("ACCT") && s.contains("UIDU") && s.contains("GIDU"));
            // Managed = a home on the shared mount.
            assert!(s.contains("/efs/home"));
            assert!(s.contains("/etc/passwd") && s.contains("/etc/group"));
            // The UIDU/GIDU sweeps carry no range or home filter.
            let uidu = s.lines().find(|l| l.contains("UIDU")).expect("UIDU line");
            assert!(
                !uidu.contains("efs/home") && !uidu.contains(">= 1000"),
                "the in-use table must be unfiltered: {uidu}"
            );
        }



        /// The create must carry the number the pre-flight chose from both
        /// bastions. Losing it silently returns to the script's local pick —
        /// which is the bug: it can only see the box it runs on.
        #[test]
        fn the_create_run_line_carries_the_preflight_id() {
            let line = create_run_line(
                "/root/create_new_user.sh",
                "jane.doe",
                UserScriptMode::Create,
                false,
                Some(1013),
            );
            assert_eq!(
                line,
                "bash /root/create_new_user.sh --user jane.doe --uid 1013"
            );

            let sudo = create_run_line(
                "/root/create_new_user.sh",
                "jane.doe",
                UserScriptMode::Create,
                true,
                Some(1013),
            );
            assert_eq!(
                sudo,
                "bash /root/create_new_user.sh --user jane.doe --uid 1013 --sudo"
            );
        }

        /// Without a chosen id the line must stay exactly as it was, so a
        /// pre-flight that could not run still produces a working command.
        #[test]
        fn a_create_with_no_chosen_id_is_unchanged() {
            assert_eq!(
                create_run_line("/p.sh", "jane.doe", UserScriptMode::Create, false, None),
                "bash /p.sh --user jane.doe"
            );
            assert_eq!(
                create_run_line("/p.sh", "jane.doe", UserScriptMode::Create, true, None),
                "bash /p.sh --user jane.doe --sudo"
            );
        }

        /// Restore allocates nothing and must never re-apply sudo: the account
        /// exists, keeps its uid, and an existing grant is left alone.
        #[test]
        fn restore_takes_neither_an_id_nor_sudo() {
            for (sudo, uid) in [(false, None), (true, Some(1013))] {
                assert_eq!(
                    create_run_line("/p.sh", "jane.doe", UserScriptMode::Restore, sudo, uid),
                    "bash /p.sh --user jane.doe --restore"
                );
            }
        }

        /// `done` is the sign-in script's last word, so it is the one step
        /// that is not still in progress. Green, and the same green as
        /// `ScriptState::Ok`, so "this worked" reads the same across the bar.
        #[test]
        fn a_finished_sign_in_is_green_and_the_steps_before_it_are_not() {
            let green = egui::Color32::from_rgb(120, 180, 120);
            let (color, text) =
                fed_status_for(&FedState::SigningIn("done".to_string())).expect("a line");
            assert_eq!(color, green);
            assert_eq!(text, "fed up: signing in — done");
            assert!(!text.ends_with('…'), "done is not still happening: {text}");

            for step in ["entering-code", "entering-password", "confirming-mfa"] {
                let (color, text) =
                    fed_status_for(&FedState::SigningIn(step.to_string())).expect("a line");
                assert_ne!(color, green, "{step} is still in progress");
                assert!(text.ends_with('…'), "{text}");
            }
        }

        /// The colours that carry meaning must not drift: only a stand-down is
        /// red, and a retry stays amber because it usually fixes itself.
        #[test]
        fn only_a_stand_down_is_red() {
            let red = egui::Color32::from_rgb(220, 80, 80);
            use ec2_manager::fed_auth::FedError;
            let (color, _) =
                fed_status_for(&FedState::Stalled(FedError::Command("nope".into()))).expect("line");
            assert_eq!(color, red);
            let (color, _) = fed_status_for(&FedState::Retrying {
                error: FedError::Command("nope".into()),
                attempt: 2,
            })
            .expect("line");
            assert_ne!(color, red, "a retry is still working");
            assert!(fed_status_for(&FedState::Authenticated).is_none());

            // Running is work in progress, in the same yellow the script
            // status bar uses for it — not the grey of something idle.
            let (color, text) = fed_status_for(&FedState::Running).expect("line");
            assert_eq!(color, egui::Color32::from_rgb(255, 205, 0));
            assert!(text.ends_with('…'), "{text}");
        }

        /// Every status-coloured label goes through `note_label`, so a stray
        /// direct call would be a notification that stays thin on a light
        /// panel — the exact thing this fixes, and invisible in review. The
        /// only two allowed are the deliberately-grey ones, where weight would
        /// fight the colour's purpose.
        #[test]
        fn status_coloured_labels_all_carry_the_light_theme_weight() {
            // Built at runtime: spelled out, this test's own source would
            // match itself and the count would be meaningless.
            let needle = format!("ui.{}(", "colored_label");
            let src = include_str!("ec2_manager_gui.rs");
            let lines: Vec<(usize, &str)> = src
                .lines()
                .enumerate()
                .filter(|(_, l)| l.contains(&needle))
                .collect();
            assert_eq!(
                lines.len(),
                2,
                "only the two grey labels may bypass note_label; found:\n{}",
                lines
                    .iter()
                    .map(|(i, l)| format!("{}: {}", i + 1, l.trim()))
                    .collect::<Vec<_>>()
                    .join("\n")
            );
            // ...and they must still be the grey ones. The colour sits on the
            // following line in both, so look at a small window.
            let all: Vec<&str> = src.lines().collect();
            for (i, line) in &lines {
                let window = all[*i..(*i + 3).min(all.len())].join(" ");
                assert!(
                    window.contains("Color32::GRAY"),
                    "a non-grey label bypassed note_label at line {}: {}",
                    i + 1,
                    line.trim()
                );
            }
        }

        /// A protected name needs BOTH ticks. The everyday confirmation is
        /// given on every delete and so stops being read; the second one is
        /// the one that actually stops someone.
        #[test]
        fn deleting_a_protected_user_takes_a_second_confirmation() {
            // Ordinary user: one tick is enough, and the protected box is
            // irrelevant because it is never shown.
            assert!(delete_confirmed(false, true, false));
            assert!(!delete_confirmed(false, false, false));

            // Protected user: one tick is not enough.
            assert!(!delete_confirmed(true, true, false));
            assert!(delete_confirmed(true, true, true));

            // And the second never substitutes for the first — ticking only
            // the protected box must not arm the button.
            assert!(!delete_confirmed(true, false, true));
        }

        #[test]
        fn sudoers_grant_template_splits_into_four_steps() {
            let s = deobf_asset(include_bytes!(concat!(env!("OUT_DIR"), "/sudoers_grant.sh.obf")))
                .replace("__USER__", "jane.doe")
                .replace("__SUFFIX__", "jane-doe");
            let steps: Vec<&str> = s.lines().collect();
            assert_eq!(steps.len(), 4, "must yield exactly 4 sudoers steps");
            assert_eq!(
                steps[0],
                "echo 'jane.doe ALL=(ALL) NOPASSWD:ALL' | tee /etc/sudoers.d/zz-jane-doe-nopasswd > /dev/null"
            );
            assert_eq!(steps[1], "visudo -cf /etc/sudoers.d/zz-jane-doe-nopasswd");
            assert_eq!(steps[2], "chmod 0440 /etc/sudoers.d/zz-jane-doe-nopasswd");
            assert_eq!(steps[3], "chown root:root /etc/sudoers.d/zz-jane-doe-nopasswd");
        }

        #[test]
        fn format_aws_time_local_normalizes_to_one_instant() {
            // Same moment, expressed two ways. Whatever the test machine's
            // timezone is, both must render identically — that only holds if
            // the value is genuinely converted rather than reformatted.
            let utc = format_aws_time_local("2026-03-11T16:03:45+00:00");
            let offset = format_aws_time_local("2026-03-11T11:03:45-05:00");
            assert_eq!(utc, offset);
            // And the zone is always spelled out for the user.
            assert!(utc.contains("UTC+") || utc.contains("UTC-"), "got {utc}");
            // Reformatted, not passed through raw.
            assert_ne!(utc, "2026-03-11T16:03:45+00:00");
        }

