        #[test]
        fn highlight_bash_round_trips_every_byte() {
            // The galley must stay byte-for-byte identical to the buffer, or the
            // TextEdit cursor/selection desync. `LayoutJob::text` is the exact
            // concatenation of every appended slice.
            let font = egui::FontId::monospace(12.0);
            let samples = [
                "",
                "#!/bin/bash\n# a comment\necho \"hello $USER\" # trailing\n",
                "for i in 1 2 3; do\n  echo ${i}\ndone\n",
                "grep -vF '@github.com' file 2>&1 | sort\n",
                "x='unterminated\nnext line\n",
                "path=/home/efs/{{user}} && café ☕ = $HOME\n",
                "foo#bar not-a-comment $? $@ $(date)\n",
                "f() { echo $(( (1 + 2) * [3] )); }\n",
                "case \"$x\" in\n  start) run ;;\nesac\n",
                "unbalanced ) ] } ( [ {\n",
            ];
            for s in samples {
                for dark in [true, false] {
                    let job = highlight_bash(s, font.clone(), dark);
                    assert_eq!(job.text, s, "round-trip failed (dark={dark}) for {s:?}");
                }
            }
        }

        #[test]
        fn highlight_bash_colours_brackets_by_depth() {
            let font = egui::FontId::monospace(12.0);
            let pal = BashPalette::for_theme(true);
            // Colour of the single byte at `at`, per the job's section list.
            let color_at = |text: &str, at: usize| {
                let job = highlight_bash(text, font.clone(), true);
                job.sections
                    .iter()
                    .find(|s| s.byte_range.contains(&at))
                    .map(|s| s.format.color)
                    .expect("byte covered by exactly one section")
            };

            // `( [ { } ] )` — depth cycles 0,1,2 out and back on the way in.
            let s = "([{}])";
            assert_eq!(color_at(s, 0), pal.bracket[0]);
            assert_eq!(color_at(s, 1), pal.bracket[1]);
            assert_eq!(color_at(s, 2), pal.bracket[2]);
            assert_eq!(color_at(s, 3), pal.bracket[2]);
            assert_eq!(color_at(s, 4), pal.bracket[1]);
            assert_eq!(color_at(s, 5), pal.bracket[0]);

            // A fourth level wraps back to the first colour.
            assert_eq!(color_at("(((( ", 3), pal.bracket[0]);

            // `case` patterns and other stray closers stay plain.
            assert_eq!(color_at("  start) run", 7), pal.default);
            // A mismatched closer doesn't pop the stack, so the real `)` still
            // closes at depth 0.
            let s = "(a] b)";
            assert_eq!(color_at(s, 2), pal.default);
            assert_eq!(color_at(s, 5), pal.bracket[0]);

            // Brackets inside comments and strings never affect the depth.
            let s = "# ((\n'[[' ()";
            assert_eq!(color_at(s, 2), pal.comment);
            assert_eq!(color_at(s, 6), pal.string);
            assert_eq!(color_at(s, 10), pal.bracket[0]);

            // `${…}` keeps its variable colour rather than being split.
            assert_eq!(color_at("${HOME}", 6), pal.variable);
        }

        fn cred<'a>(user: &'a str, pat: &'a str, host: &'a str) -> GitCredential<'a> {
            GitCredential { user, pat, host }
        }

        #[test]
        fn prep_terminal_populates_the_credential_store_when_set() {
            let bytes = prep_terminal_command(Some(cred("bconrad", "abc123", "github.com")));
            let text = String::from_utf8_lossy(&bytes);
            // Enables the store helper and writes the host's URL with the PAT.
            assert!(text.contains("git config --global credential.helper store"));
            assert!(text.contains("https://bconrad:abc123@github.com"));
            // Drops any stale line for this host before re-adding it.
            assert!(text.contains("grep -vF '@github.com'"));
            // Leading space + ignorespace keeps the token out of bash history.
            assert!(text.contains("HISTCONTROL=ignorespace"));
            // …and the setup lands before the clear that hides it.
            assert!(text.ends_with("clear\r"));
            assert_eq!(text.matches("clear\r").count(), 1);
        }

        #[test]
        fn prep_terminal_scopes_to_the_configured_host() {
            let bytes = prep_terminal_command(Some(cred("u", "t", "git.internal")));
            let text = String::from_utf8_lossy(&bytes);
            assert!(text.contains("https://u:t@git.internal"));
            assert!(!text.contains("github.com"));
        }

        #[test]
        fn prep_terminal_omits_git_setup_without_a_pat() {
            let none: Option<GitCredential<'_>> = None;
            for git_cred in [none, Some(cred("bconrad", "", "github.com"))] {
                let bytes = prep_terminal_command(git_cred);
                let text = String::from_utf8_lossy(&bytes);
                assert!(!text.contains("git-credentials"), "unexpected setup: {text}");
                assert!(!text.contains("credential.helper"), "unexpected setup: {text}");
                assert!(text.starts_with("exec bash\r"));
                assert!(text.ends_with("clear\r"));
            }
        }

        /// A quote in the token must not break out of the printf argument.
        #[test]
        fn prep_terminal_quotes_a_pat_containing_a_quote() {
            let bytes = prep_terminal_command(Some(cred("u", "a'b", "github.com")));
            let text = String::from_utf8_lossy(&bytes);
            assert!(text.contains(r"https://u:a'\''b@github.com"), "{text}");
        }

        #[test]
        fn git_auth_failures_are_recognised() {
            assert!(looks_like_git_auth_failure(
                "remote: Invalid username or password.\nfatal: Authentication failed for 'https://…'"
            ));
            assert!(looks_like_git_auth_failure(
                "remote: HTTP Basic: Access denied"
            ));
            assert!(looks_like_git_auth_failure(
                "fatal: could not read Username for 'https://github.com': No such device"
            ));
            assert!(!looks_like_git_auth_failure("Already up to date."));
            assert!(!looks_like_git_auth_failure(""));
        }

        /// The API reports UTC; the table must show the machine's local clock.
        #[test]
        fn alert_time_is_rendered_in_local_zone() {
            let utc = "2026-07-13T15:21:12.874Z";
            let rendered = format_local_time(utc);
            let expected = chrono::DateTime::parse_from_rfc3339(utc)
                .expect("sample parses")
                .with_timezone(&chrono::Local)
                .format("%b %d %-I:%M:%S %p")
                .to_string();
            assert_eq!(rendered, expected);
            // 12-hour clock with a meridiem, not the raw UTC string.
            assert!(rendered.ends_with("AM") || rendered.ends_with("PM"));
            assert!(!rendered.contains('Z'));
        }

